int[][] gridDist(int[][] grid, int sr, int sc) {   // BFS; -1 = unreachable, 1 = wall
    int R = grid.length, C = grid[0].length;
    int[][] dist = new int[R][C];
    for (int[] row : dist) Arrays.fill(row, -1);
    Deque<int[]> q = new ArrayDeque<>(List.of(new int[]{sr, sc}));
    dist[sr][sc] = 0;                              // mark when enqueued, not when polled
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!q.isEmpty()) {
        int[] cur = q.poll();
        for (int[] d : dirs) {
            int r = cur[0] + d[0], c = cur[1] + d[1];
            if (r < 0 || r >= R || c < 0 || c >= C || grid[r][c] == 1 || dist[r][c] != -1) continue;
            dist[r][c] = dist[cur[0]][cur[1]] + 1;
            q.offer(new int[]{r, c});
        }
    }
    return dist;
}

List<Integer> topoOrder(int n, int[][] edges) {   // edge {u, v} means u before v
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    int[] indeg = new int[n];
    for (int[] e : edges) { adj.get(e[0]).add(e[1]); indeg[e[1]]++; }
    List<Integer> order = new ArrayList<>();       // doubles as the BFS queue
    for (int i = 0; i < n; i++) if (indeg[i] == 0) order.add(i);
    for (int k = 0; k < order.size(); k++)
        for (int v : adj.get(order.get(k))) if (--indeg[v] == 0) order.add(v);
    return order.size() == n ? order : List.of();  // shorter means there is a cycle
}

List<List<Integer>> subsetsWithDup(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> out = new ArrayList<>();
    backtrack(nums, 0, new ArrayList<>(), out);
    return out;
}

void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> out) {
    out.add(new ArrayList<>(path));                 // snapshot, never the live list
    for (int i = start; i < nums.length; i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;
        path.add(nums[i]);
        backtrack(nums, i + 1, path, out);
        path.remove(path.size() - 1);
    }
}

void permute(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> out) {
    if (path.size() == nums.length) { out.add(new ArrayList<>(path)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        path.add(nums[i]);
        permute(nums, used, path, out);
        path.remove(path.size() - 1);
        used[i] = false;
    }
}

int rob(int[] nums) {                           // top-down memo
    return best(nums, 0, new Integer[nums.length]);
}

int best(int[] nums, int i, Integer[] memo) {
    if (i >= nums.length) return 0;
    if (memo[i] != null) return memo[i];
    return memo[i] = Math.max(best(nums, i + 1, memo), nums[i] + best(nums, i + 2, memo));
}

int coinChange(int[] coins, int amount) {       // bottom-up table
    int[] dp = new int[amount + 1];
    Arrays.fill(dp, amount + 1);                // "infinity" that is safe to add 1 to
    dp[0] = 0;
    for (int a = 1; a <= amount; a++)
        for (int c : coins)
            if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}

int climbStairs(int n) {                        // O(1) space rolling
    int prev = 1, cur = 1;
    for (int i = 2; i <= n; i++) { int next = prev + cur; prev = cur; cur = next; }
    return cur;
}

int lcs(String a, String b) {
    int m = a.length(), n = b.length();
    int[][] dp = new int[m + 1][n + 1];         // dp[i][j]: a[0..i) vs b[0..j)
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = a.charAt(i - 1) == b.charAt(j - 1)
                    ? dp[i - 1][j - 1] + 1
                    : Math.max(dp[i - 1][j], dp[i][j - 1]);
    return dp[m][n];
}

int editDistance(String a, String b) {
    int m = a.length(), n = b.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = a.charAt(i - 1) == b.charAt(j - 1)
                    ? dp[i - 1][j - 1]
                    : 1 + Math.min(dp[i - 1][j - 1], Math.min(dp[i - 1][j], dp[i][j - 1]));
    return dp[m][n];
}

int[][] merge(int[][] intervals) {
    Arrays.sort(intervals, (x, y) -> Integer.compare(x[0], y[0]));
    List<int[]> out = new ArrayList<>();
    for (int[] cur : intervals) {
        int[] last = out.isEmpty() ? null : out.get(out.size() - 1);
        if (last == null || last[1] < cur[0]) out.add(new int[]{cur[0], cur[1]});
        else last[1] = Math.max(last[1], cur[1]);
    }
    return out.toArray(new int[0][]);
}

int minRooms(int[][] meetings) {
    Arrays.sort(meetings, (x, y) -> Integer.compare(x[0], y[0]));
    PriorityQueue<Integer> ends = new PriorityQueue<>();
    for (int[] m : meetings) {
        if (!ends.isEmpty() && ends.peek() <= m[0]) ends.poll();   // reuse a freed room
        ends.offer(m[1]);
    }
    return ends.size();
}

int eraseOverlaps(int[][] iv) {                 // fewest removals so none overlap
    Arrays.sort(iv, (x, y) -> Integer.compare(x[1], y[1]));
    int kept = 0, end = Integer.MIN_VALUE;
    for (int[] x : iv) if (x[0] >= end) { kept++; end = x[1]; }
    return iv.length - kept;
}

class UnionFind {
    private final int[] parent, rank;
    UnionFind(int n) { parent = new int[n]; rank = new int[n]; Arrays.setAll(parent, i -> i); }
    int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
    boolean union(int a, int b) {               // false if already connected
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;
        return true;
    }
}

class Trie {
    private final Trie[] kids = new Trie[26];
    private boolean word;
    void insert(String w) {
        Trie t = this;
        for (char c : w.toCharArray())
            t = t.kids[c - 'a'] != null ? t.kids[c - 'a'] : (t.kids[c - 'a'] = new Trie());
        t.word = true;
    }
    boolean search(String w, boolean prefixOk) {
        Trie t = this;
        for (char c : w.toCharArray()) if ((t = t.kids[c - 'a']) == null) return false;
        return prefixOk || t.word;
    }
}
